PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, org TEXT NOT NULL REFERENCES organizations(id), department TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS inspections(id TEXT NOT NULL,org TEXT NOT NULL,department TEXT NOT NULL,officer TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, content TEXT NOT NULL, evidence BLOB NOT NULL, updated TEXT NOT NULL, PRIMARY KEY(org,id));
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY,org TEXT NOT NULL,department TEXT NOT NULL,actor TEXT NOT NULL,inspection TEXT NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL, timestamp TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id TEXT NOT NULL,user TEXT NOT NULL,org TEXT NOT NULL,department TEXT NOT NULL,last_seen TEXT NOT NULL,PRIMARY KEY(id,user));